import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        good_letters_str = next(iterator)
        pattern = next(iterator)
        n = int(next(iterator))
        queries = []
        for _ in range(n):
            queries.append(next(iterator))
    except StopIteration:
        return

    good_set = set(good_letters_str)

    star_index = -1
    for i, char in enumerate(pattern):
        if char == '*':
            star_index = i
            break

    results = []

    for q in queries:
        q_len = len(q)
        p_len = len(pattern)

        if star_index == -1:
            # No star: lengths must be equal
            if q_len != p_len:
                results.append("NO")
                continue

            match = True
            for i in range(p_len):
                p_char = pattern[i]
                q_char = q[i]

                if p_char == '?':
                    if q_char not in good_set:
                        match = False
                        break
                elif p_char == '*':
                    # Should not happen here
                    pass
                else:
                    if p_char != q_char:
                        match = False
                        break

            if match:
                results.append("YES")
            else:
                results.append("NO")
        else:
            # Star exists
            # Pattern parts: prefix (before *), suffix (after *)
            # Query must match prefix at start, suffix at end
            # Middle part must consist only of bad letters

            prefix_len = star_index
            suffix_len = p_len - star_index - 1

            # Check if query is long enough to cover prefix and suffix
            if q_len < prefix_len + suffix_len:
                results.append("NO")
                continue

            # Check prefix
            match = True
            for i in range(prefix_len):
                p_char = pattern[i]
                q_char =q[i]

                if p_char == '?':
                    if qchar not in good_set:
                        match = False
                        break
                else:
                    if p_char != q_char:
                        # Note: p_char cannot be '*' here
                        match = False
                        break

            if not match:
                results.append("NO")
                continue

            # Check suffix
            # Suffix in pattern starts at star_index + 1
            # Corresponding part in query ends at q_len
            # We need to align the end of query with the end of pattern suffix

            # Pattern suffix indices: star_index+1 to p_len-1
            # Query suffix indices: q_len - suffix_len to q_len - 1

            for i in range(suffix_len):
                p_idx = star_index + 1 + i
                q_idx = q_len - suffix_len + i

                p_char = pattern[p_idx]
                q_char = q[q_idx]

                if p_char == '?':
                    if q_char in good_set:
                        continue
                    else:
                        match = False
                        break
                else:
                    # p_char is a literal letter
                    if p_char != q_char:
                        match = False
            if not match:
                results.append("NO")
                continue

            # Check middle part (replaced by *)
            # Middle part in query: from prefix_len to q_len - suffix_len
            # Must contain only bad letters

            mid_start = prefix_len
            mid_end = q_len - suffix_len

            for i in range(mid_start, mid_end):
                q_char = q[i]
                if q_char in good_set:
                    match = False
                    break

            if match:
                results.append("YES")
            elif not match:
                results.append("NO")

    print('\n'.join(results))

